    ('bbbbbbbb-0000-0000-0009-000000000005'::uuid, 'ציפיתי ללמוד לבשל, ובפועל בעיקר צפיתי בשף מבשל. בכמה מפגשים לא נגעתי בסיר בכלל, כי היו יותר מדי אנשים בכל עמדה. האוכל שטעמנו היה מצוין, אבל את המיומנות לא קיבלתי. לא ממליץ במחיר הזה.'),
    ('bbbbbbbb-0000-0000-0009-000000000006'::uuid, 'באמצע הקורס חלק מהמפגשים עברו לזום בלי הסבר טוב, ולמי שאין ציוד בבית זה היה מתסכל. את הפסטה למדתי, אבל את הריזוטו והרטבים לא הייתי יודעת להכין לבד. לא הייתי נרשמת שוב.'),
    ('bbbbbbbb-0000-0000-0010-000000000002'::uuid, 'שנים צילמתי באוטומטי. אחרי שלושה מפגשים כבר עבדתי במצב ידני, ובמפגש החמישי הבנתי סוף סוף מה הקשר בין הצמצם לחדות. המשוב על התמונות היה ישיר ולפעמים לא נעים, אבל הוא מה שקידם אותי.'),
    ('bbbbbbbb-0000-0000-0010-000000000003'::uuid, 'היציאות לצלם בחוץ, בשוק ובשכונה, היו החלק הכי טוב. בכיתה ההסבר על היסטוגרמה היה מהיר מדי, ונאלצתי לחפש סרטונים בבית. הפרק על עריכה היה קצר, כמעט רק הדגמה.'),
    ('bbbbbbbb-0000-0000-0010-000000000004'::uuid, 'קבוצה קטנה, מורה שזוכר את התמונות של כל אחד, ושיעורי בית שבאמת עושים. בסוף הקורס כל אחד הציג חמש תמונות, ופתאום ראיתי כמה השתפרתי מהמפגש הראשון.'),
    ('bbbbbbbb-0000-0000-0010-000000000005'::uuid, 'קניתי מצלמה לפני שנה והיא ישבה בארון. הקורס הוציא אותה החוצה. המפגש על אור טבעי שינה את הדרך שבה אני מסתכל על תמונות, ואני מצלם עכשיו בעיקר בשעה שלפני השקיעה.'),
    ('bbbbbbbb-0000-0000-0010-000000000006'::uuid, 'טוב למתחילים. מי שכבר מכיר את המצלמה ישתעמם במפגש הראשון. העריכה הבסיסית קיבלה מפגש אחד, וזה לא מספיק. מצד שני, המחיר הוגן לשמונה מפגשים בקבוצה קטנה.'),
    ('bbbbbbbb-0000-0000-0010-000000000007'::uuid, 'הקורס לא התאים לי. יש לי מצלמה פשוטה בלי מצב ידני, וכתוב בתנאי הקבלה שצריך מצלמה כזאת, אבל בטלפון אמרו לי שזה לא משנה. בפועל חצי מהתרגילים לא יכולתי לעשות. כדאי לבדוק את הציוד לפני שנרשמים.'),
    ('bbbbbbbb-0000-0000-0011-000000000002'::uuid, 'ארבעה מפגשים קצרים בזום, וכל אחד נגמר במשימה לשבוע. הכי שימושי היה החלק על עריכה באפליקציה: שלושה כלים שאני משתמשת בהם בכל תמונה. במחיר הזה זה שווה, אבל אל תצפו ליותר מהבסיס.'),
    ('bbbbbbbb-0000-0000-0012-000000000002'::uuid, 'המורים טובים, ובחשיבה כמותית יש שיטה ברורה לכל סוג של שאלה. המחיר גבוה, וזה מורגש כשמשווים לקורסים אונליין. מה שהצדיק אותו בשבילי: מבחן בתנאי אמת כל שבועיים, באותה שעה של המבחן האמיתי.'),
    ('bbbbbbbb-0000-0000-0012-000000000003'::uuid, 'לא עליתי ב-60 נקודות, והבקשה לקורס חוזר בחינם נתקעה בתנאים: צריך נוכחות של 90 אחוז ולהגיש את כל המבחנים, ופספסתי שניים בגלל עבודה. בחשיבה מילולית הרגשתי שאנחנו רצים על החומר. לא הייתי נרשם שוב.'),
    ('bbbbbbbb-0000-0000-0012-000000000004'::uuid, 'אבי מסביר כמותית כמו שאף מורה בתיכון לא הסביר לי. עליתי 70 נקודות מהמבחן הראשון ועד המבחן האמיתי. החיסרון: באר שבע רחוקה ממני, ובערבי חורף הנסיעה הייתה קשה. המחיר כבד למי שעוד לא עובד.'),
    ('bbbbbbbb-0000-0000-0012-000000000005'::uuid, 'מסגרת שמחייבת להתאמן. לבד לא הייתי פותחת ספר, וכאן היו שיעורי בית ובדיקה בכל מפגש. האנגלית הייתה החלק הכי טוב, עם אוצר מילים שחוזר במבחן.'),
    ('bbbbbbbb-0000-0000-0012-000000000006'::uuid, 'קורס יסודי, אבל צפוף: ארבע שעות אחרי יום עבודה זה הרבה, ובשעה האחרונה כבר לא קלטתי. עברתי עם ציון שהספיק לתואר שרציתי. הייתי מוותר על חלק מהשיעורים המילוליים לטובת עוד תרגול.'),
    ('bbbbbbbb-0000-0000-0012-000000000007'::uuid, 'לא הגעתי לציון שהייתי צריך. בחשיבה מילולית היה מורה מחליף במשך חודש, והקצב היה לא אחיד. הכמותי היה טוב, אבל זה לא הספיק. מי שחלש במילולי, שיבדוק אם יש תגבור נפרד.'),
    ('bbbbbbbb-0000-0000-0012-000000000008'::uuid, 'קיבלתי ספרים, גישה למאגר שאלות וחמישה מבחני תרגול מלאים. המאגר שווה הרבה, ואני ממשיכה להשתמש בו לקראת מועד נוסף. המחיר לא נמוך, אבל ברור על מה משלמים.'),
    ('bbbbbbbb-0000-0000-0012-000000000009'::uuid, 'קבוצה של 20 איש עם רמות שונות מאוד. המורים ניסו להתאים לכולם, ולפעמים זה אומר שהחזקים מחכים. עברתי ושיפרתי ב-55 נקודות, קצת פחות ממה שהובטח, אבל מספיק בשבילי.'),
    ('bbbbbbbb-0000-0000-0013-000000000002'::uuid, 'השיעורים המוקלטים קצרים ומחולקים לפי נושא, אז אפשר לחזור בדיוק על מה שלא הבנתי. שילמתי פחות מחצי ממחיר של קורס בכיתה. בלי משמעת עצמית זה לא יעבוד, ואני נעזרתי בלוח זמנים שבניתי לעצמי מהשבוע הראשון.'),
    ('bbbbbbbb-0000-0000-0013-000000000003'::uuid, 'ההקלטות ישנות, ובחלק מהן המרצה מתייחס לשאלות שכבר לא מופיעות ככה במבחן. במפגש השבועי בזום היו עשרות אנשים, ורוב השאלות שלי נשארו בלי מענה. לא הגעתי ליעד שהצבתי לעצמי, ולא הייתי בוחר שוב בקורס בקצב אישי.'),
    ('bbbbbbbb-0000-0000-0014-000000000002'::uuid, 'החומר מסודר בחוברות לפי נושא, ובכל מפגש פותרים תרגילים מהמבחנים של השנים הקודמות. הקצב איטי בהתחלה ומתגבר לקראת מע״מ. עברתי במועד הראשון.'),
    ('bbbbbbbb-0000-0000-0014-000000000003'::uuid, 'בשביל קורס בבוקר, פעמיים בשבוע, המחיר הוגן מאוד. המרצה מסבירה פקודות יומן בדוגמאות מעסקים קטנים, וזה הפך את החומר לפחות יבש. היום אני מנהלת חשבונות מתחילה במשרד של רואה חשבון.'),
    ('bbbbbbbb-0000-0000-0014-000000000004'::uuid, 'הכיתה גדולה, ולא תמיד יש זמן לשאלות. אבל המרצה נשארת אחרי השיעור ועונה לכל מי שמחכה, וגם במייל. התרגול לקראת המבחן החיצוני היה בדיוק ברמה של המבחן.'),
    ('bbbbbbbb-0000-0000-0014-000000000005'::uuid, 'חזרתי ללמוד אחרי עשרים שנה בלי שום לימודים מסודרים. הפחד הכי גדול שלי היה המבחן, והמבחנים לדוגמה בכיתה הורידו אותו. עברתי עם 88. הקורס לא נותן תעודה בעצמו, אבל ההכנה למבחן החיצוני רצינית.'),
    ('bbbbbbbb-0000-0000-0014-000000000006'::uuid, 'נכשלתי במבחן החיצוני, בעיקר בחלק של מע״מ. הנושא קיבל שלושה מפגשים, והרגשתי שרצנו עליו בסוף הקורס. המרצה טובה, אבל הייתי צריך עוד תרגול, ולא היה מפגש חזרה. אני ניגש שוב, הפעם עם מורה פרטי.')
  ) as v(id, body)
  where r.id = v.id
    and r.body like 'ביקורת לדוגמה מספר %'
  returning r.id
)
select count(*) as reviews_updated from updated;
